solution.code:
function hammingWeightImpl(n) {
  let count = 0;
  while (n !== 0) {
    n &= (n - 1);
    count++;
  }
  return count;
}

function hammingDistanceImpl(x, y) {
  return hammingWeightImpl(x ^ y);
}

