function countBitsImpl(n) {
  const dp = new Array(n+1).fill(0);
  for (let i=1;i<=n;i++) dp[i]=dp[i>>1]+(i&1);
  return dp;
}

function countBitsV2Impl(n) {
  const dp = new Array(n+1).fill(0);
  for (let i=1;i<=n;i++) dp[i]=dp[i&(i-1)]+1;
  return dp;
}

