solution.code:
function getSumImpl(a, b) {
  const MASK = 0xFFFFFFFF;
  const MAX  = 0x7FFFFFFF;
  while (b !== 0) {
    const carry = ((a & b) << 1) & MASK;
    a = (a ^ b) & MASK;
    b = carry;
  }
  return a <= MAX ? a : ~(a ^ MASK);
}
